// lib/collection/src/operations/types.rs line 1736-1743
pub fn check_vector_names(&self, collection: &CollectionParams) -> CollectionResult<()> {
    for vector_name in self.0.keys() {
        collection
            .vectors
            .get_params(vector_name)
            .map(|_| ())
            .ok_or_else(|| OperationError::vector_name_not_exists(vector_name.clone()))?;
    }
    Ok(())
}
